import { Component, OnInit, Output, EventEmitter } from '@angular/core';
import { EmailService } from '../../core/services/email.service';
import { ThemeService } from '../../core/services/theme.service';

interface NavItem {
  id: string;
  label: string;
  icon: string;
  folder: 'inbox' | 'sent' | 'drafts' | 'trash';
  count?: number;
}

@Component({
  selector: 'app-sidebar',
  templateUrl: './sidebar.component.html',
  styleUrls: ['./sidebar.component.scss']
})
export class SidebarComponent implements OnInit {
  @Output() folderChange = new EventEmitter<string>();

  activeFolder = 'inbox';
  isDark = false;

  navItems: NavItem[] = [
    { id: 'inbox', label: 'Inbox', icon: 'inbox', folder: 'inbox' },
    { id: 'sent', label: 'Sent', icon: 'send', folder: 'sent' },
    { id: 'drafts', label: 'Drafts', icon: 'draft', folder: 'drafts' },
    { id: 'trash', label: 'Trash', icon: 'trash', folder: 'trash' },
    { id: 'star' , label: 'Starred', icon: 'star' ,folder: 'trash'}
  ];

  constructor(
    private emailService: EmailService,
    private themeService: ThemeService
  ) {}

  ngOnInit(): void {
    this.emailService.getFolderCounts().subscribe(counts => {
      this.navItems = this.navItems.map(item => ({
        ...item,
        count: counts[item.id] || undefined
      }));
    });

    this.themeService.isDark$.subscribe(isDark => this.isDark = isDark);
  }

  selectFolder(folder: string): void {
    this.activeFolder = folder;
    this.folderChange.emit(folder);
  }

  toggleTheme(): void {
    this.themeService.toggle();
  }
}
<aside class="sidebar">
  <!-- Logo -->
  <div class="sidebar__logo">
    <div class="sidebar__logo-mark">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
        <rect width="20" height="20" rx="6"/>
        <path d="M3 7l7 5 7-5" stroke="black" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        <rect x="3" y="6" width="16" height="12" rx="2" stroke="black" stroke-width="1.5"/>
      </svg>
    </div>
    <span class="sidebar__logo-name">Mailbox</span>
  </div>

  <!-- Compose Button -->
  <button class="sidebar__compose">
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
      <path d="M8 3v10M3 8h10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
    </svg>
    Compose
  </button>

  <!-- Navigation -->
  <nav class="sidebar__nav">
    <p class="sidebar__nav-label">Folders</p>
    <ul>
      <li *ngFor="let item of navItems">
        <button
          class="sidebar__nav-item"
          [class.sidebar__nav-item--active]="activeFolder === item.id"
          (click)="selectFolder(item.id)">
          <span class="sidebar__nav-icon">
            <img
  *ngIf="item.icon === 'inbox'"
  src="assets/avatars/icon.png"
  width="18"
  height="18"
  alt="inbox icon"
/>
<img
  *ngIf="item.icon === 'star'"
  src="assets/avatars/star.png"
  width="18"
  height="18"
  alt="star icon"
/>


            <img
  *ngIf="item.icon === 'send'"
  src="assets/avatars/arrow.png"
  width="18"
  height="18"
  alt="send icon"
/>

            <img
  *ngIf="item.icon === 'draft'"
  src="assets/avatars/drafts.png"
  width="18"
  height="18"
  alt="draft icon"
/>

<img
  *ngIf="item.icon === 'star'"
  src="assets/avatars/star.png"
  width="18"
  height="18"
  alt="star icon"
/>

            <img
  *ngIf="item.icon === 'trash'"
  src="assets/avatars/del.png"
  width="18"
  height="18"
  alt="delete icon"
/>
          </span>
          <span class="sidebar__nav-label-text">{{ item.label }}</span>
          <span class="sidebar__nav-badge" *ngIf="item.count && item.count > 0">{{ item.count }}</span>
        </button>
      </li>
    </ul>
  </nav>



    <div class="sidebar__user">
      <div class="sidebar__user-avatar">K</div>
      <div class="sidebar__user-info">
        <p class="sidebar__user-name">Keerthi</p>
        <p class="sidebar__user-email">keerthi@mail.com</p>
      </div>
    </div>
</aside>
